"""Signed jump-table guards, using generated bytes rather than game code."""
import struct
import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'games/totk/third_party/d2r'))
from jump_table import signed_table_span


class SignedTables(unittest.TestCase):
    def setUp(self):
        self.image = bytearray(0x800)
        self.dispatch = bytes(range(20))
        self.image[0x100:0x114] = self.dispatch
        self.offsets = (-0x300, -0x2e0, -0x2fc)
        struct.pack_into('<3i', self.image, 0x400, *self.offsets)
        self.descriptor = (0x400, 0x400, self.offsets, self.dispatch.hex())

    def test_negative_offsets_use_text_targets_not_rodata_as_the_pad_base(self):
        self.assertEqual(signed_table_span(self.image, 0x110, 0x300, self.descriptor), (0x100, 9))

    def test_changed_dispatch_or_table_is_rejected(self):
        for offset in (0x100, 0x400):
            with self.subTest(offset=offset):
                image = self.image.copy()
                image[offset] ^= 1
                with self.assertRaises(AssertionError):
                    signed_table_span(image, 0x110, 0x300, self.descriptor)

    def test_misaligned_and_out_of_text_targets_are_rejected(self):
        for base in (0x401, 0x200, 0x700):
            with self.subTest(base=base), self.assertRaises(AssertionError):
                signed_table_span(self.image, 0x110, 0x300,
                                  (base, *self.descriptor[1:]))

    def test_truncated_table_is_rejected(self):
        with self.assertRaises(struct.error):
            signed_table_span(self.image[:0x408], 0x110, 0x300, self.descriptor)
